
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_pg1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_pg1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.020958386957636e+02, 9.846801668376720e+01, 9.351121632633995e+01, 8.688996875306169e+01, 7.832880645711164e+01, 6.776764291819615e+01, 5.559717769855918e+01, 4.290213117188650e+01, 3.144979655091256e+01, 2.253544337876449e+01, 1.264563753883281e+01, 3.038131235385656e+00, 2.005055151637010e+00, 1.488071156261911e+00, 1.014047680701137e+00, 7.763595056005635e-01, 7.069641719704302e-01, 6.482679336939907e-01, 6.034971624558374e-01, 5.743491734340817e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


